package org.example.behavioral_pattern.observer_pattern.demo;import java.util.ArrayList;import java.util.List;public class FacebookNewsFeed implements Subject {    private final List<Observer> observers = new ArrayList<>();    @Override    public void attach(Observer o) {        observers.add(o);    }    @Override    public void detach(Observer o) {        observers.remove(o);    }    @Override    public void notifyObservers(String message) {        for (Observer o : observers) {            o.update(message);        }    }    public void postStatus(String status) {        System.out.println("📢 NewsFeed: " + status);        notifyObservers(status);    }}